// ✅ NEW: A custom loader isolates each plugin's dependencies so
// different versions can coexist, while STILL delegating JDK classes
// to the parent (never reload java.lang).
public class PluginLoader extends ClassLoader {
  private final java.nio.file.Path pluginDir;

  public PluginLoader(java.nio.file.Path dir, ClassLoader parent) {
    super(parent); // ✅ NEW: keep bootstrap/platform/app delegation for core
    this.pluginDir = dir;
  }

  // ✅ NEW: override findClass (not loadClass) to preserve delegation
  // for everything the parent can provide.
  @Override
  protected Class<?> findClass(String name) throws ClassNotFoundException {
    try {
      byte[] bytes = java.nio.file.Files.readAllBytes(
          pluginDir.resolve(name.replace('.', '/') + ".class"));
      return defineClass(name, bytes, 0, bytes.length);
    } catch (java.io.IOException e) {
      throw new ClassNotFoundException(name, e);
    }
  }
}

// Each plugin gets its own PluginLoader -> its own copy of a library
// class, isolated by (loader, name) identity.
